import manifest from "./playerImages.json";
import { indexKey } from "./nameMatch";

// Generated by `npm run fetch:images` — see scripts/fetch-player-images.mjs.
// Not committed by default (public/players/ is gitignored), so lookups may
// miss on a fresh clone until that script has been run locally.
export function imageFor(position, name) {
  return manifest[indexKey(position, name)] ?? null;
}
